import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`personal-user-manual`,heroTitle:`Turn your work data into a personality profile`,heroSubtitle:`Perplexity Computer analyzes your communication style, schedule, and decision patterns to reveal how you work, think, and collaborate.`,heroOverlaySteps:[`Connecting to your Gmail, Calendar, Slack, and Notion`,`Analyzing your communication style and decision-making patterns`,`Mapping where your time and energy actually go`,`Your personal user manual compiled — ready to share`],generatingSteps:[`Connecting to your Gmail, Calendar, Slack, and Notion to gather behavioral data`,`Designing an agent to profile your communication style, decision speed, and energy patterns`,`Configuring personality analysis across async vs. sync preferences and work rhythms`,`Setting up your personal user manual with shareable deliverables`],featureSectionTitle:`From your tools to your user manual`,featureCardTitles:[`Connects to your productivity stack`,`Outputs you can share`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Slack, Notion, Google Drive — Computer reads your real communication and scheduling patterns to build a profile based on how you actually work.`,`Communication style profile. Decision-making pattern analysis. Energy and time allocation map. A shareable user manual your team can actually use.`],capabilitySectionTitle:`Your self-awareness coach, on autopilot`,capabilitySectionSubtitle:`Connect your tools, step away, get back a detailed profile of how you work.`,capabilityCards:[{title:`Communication Analysis`,description:`Computer can analyze your emails, Slack messages, and meeting cadence — and determine whether you're an async communicator, a sync thinker, or somewhere in between.`},{title:`Decision Profiling`,description:`Computer can study how quickly you respond, how often you delegate, and where you deliberate — and map your decision-making style with real data.`},{title:`Energy Mapping`,description:`Computer can trace your calendar, focus blocks, and meeting density to show exactly where your time and energy go each week.`},{title:`Connect Your Tools`,description:`Computer can read from Gmail, Slack, Notion, and Google Drive — build your personality profile from the tools you already use every day.`},{title:`Remember & Refine`,description:`Computer can remember your past profiles and track how your patterns shift over time — so your user manual evolves as you do.`},{title:`Monitor & Alert`,description:`Computer can flag when your work patterns shift — more meetings, slower responses, calendar overload — and update your profile automatically.`}]});export{t as default};
